module altr_uart_dsync #(
   parameter RESET = 0
) (
   //Clock and Reset
   input  clk,
   input  rst_n,
   input  datain,
   output logic dataout
);

localparam RESET_VAL = (RESET == 1) ? 1'b1 : 1'b0;

logic datain_m;

always_ff @(posedge clk or negedge rst_n) begin
   if (!rst_n) {dataout, datain_m} <= {2{RESET_VAL}};
   else        {dataout, datain_m} <= {datain_m, datain};
end

